using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageGeneratedTests
{
    private const string Source = """
        using MessagePack;

        namespace MyNs
        {
            public enum MyEnum { A, B }

            [MessagePackObject]
            public class MyObject
            {
                [Key(0)] public int A { get; set; }
                [Key(1)] public MyEnum E { get; set; }
            }

            [MessagePackObject(true)]
            public class MapObject
            {
                public int C { get; set; }
            }

            [Union(0, typeof(Derived))]
            public interface IUnion { }

            [MessagePackObject]
            public class Derived : IUnion
            {
                [Key(0)] public int B { get; set; }
            }

            [GeneratedMessagePackResolver]
            partial class MyResolver { }
        }
        """;

    private static async Task<List<string>> GetTypesMissingAttributeAsync(string[] preprocessorSymbols, List<string> checkedTypes)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: preprocessorSymbols);
        SyntaxTree tree = CSharpSyntaxTree.ParseText(Source, parseOptions);
        var refs = new List<MetadataReference>(await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None));
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create("ReceiptsTestAssembly", new[] { tree }, refs, new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new global::MessagePack.SourceGenerator.MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> _);

        var missing = new List<string>();
        foreach (SyntaxTree generated in driver.GetRunResult().GeneratedTrees)
        {
            SemanticModel model = output.GetSemanticModel(generated);
            SyntaxNode root = await generated.GetRootAsync();
            foreach (ClassDeclarationSyntax cls in root.DescendantNodes().OfType<ClassDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(cls) is not INamedTypeSymbol symbol)
                {
                    continue;
                }

                bool relevant = symbol.AllInterfaces.Any(i => i.Name == "IMessagePackFormatter" || i.Name == "IFormatterResolver");
                if (!relevant)
                {
                    continue;
                }

                string name = symbol.ToDisplayString();
                if (checkedTypes.Contains(name))
                {
                    continue;
                }

                checkedTypes.Add(name);
                if (!symbol.GetAttributes().Any(a => a.AttributeClass?.Name == "ExcludeFromCodeCoverageAttribute"))
                {
                    missing.Add(name);
                }
            }
        }

        return missing;
    }

    [Fact]
    public async Task GeneratedFormattersAreExcludedFromCodeCoverage()
    {
        var checkedTypes = new List<string>();
        List<string> missing = await GetTypesMissingAttributeAsync(Array.Empty<string>(), checkedTypes);
        checkedTypes.Should().NotBeEmpty();
        missing.Should().BeEmpty();
    }

    [Fact]
    public async Task GeneratedResolverIsExcludedFromCodeCoverage()
    {
        var checkedTypes = new List<string>();
        List<string> missing = await GetTypesMissingAttributeAsync(Array.Empty<string>(), checkedTypes);
        checkedTypes.Should().Contain("MyNs.MyResolver");
        missing.Should().NotContain("MyNs.MyResolver");
    }
}

